//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_index` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        self.base_delay_ms
            .checked_shl(retry_index)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_doubles_until_it_reaches_the_cap() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 25,
            max_delay_ms: 90,
        };

        assert_eq!(config.delay_for_retry(0), 25);
        assert_eq!(config.delay_for_retry(1), 50);
        assert_eq!(config.delay_for_retry(2), 90);
        assert_eq!(config.delay_for_retry(3), 90);
    }

    #[test]
    fn huge_retry_index_cannot_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: 1_000,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), 1_000);
    }
}

